import { join } from "node:path";
import type { Plugin, PluginContext } from "rollup";
import spdxExpressionParse from "spdx-expression-parse";
import * as CDX from "@cyclonedx/cyclonedx-library";
import type { ComponentType } from "@cyclonedx/cyclonedx-library/Enums";

import { convertOrganizationalEntityOptionToModel, PLUGIN_ID, generatePackageId } from "./helpers";
import { autoRegisterTools } from "./tools";
import { DEFAULT_OPTIONS, type RollupPluginSbomOptions } from "./options";
import { getAllExternalModules } from "./analyzer";
import { type PackageId } from "./types/aliases";
import type { ExternalModuleInfo } from "./analyzer";
import {
    createDependencyInfoRegistry,
    aggregateDependencyInfoByModuleId,
    aggregateDependencyInfoByModulePath,
} from "./dependency-info-registry";
import { readPackage, type NormalizedPackageJson } from "./package-reader";
import { composePackageUrlFromPackageJson } from "./purl";
import {
    createVendoredPackageDetector,
    DEFAULT_MIN_MATCHED_FINGERPRINTS,
    type VendoredPackage,
} from "./vendored-packages";
import type { ModuleIdString } from "./types/aliases";

/**
 * Plugin to generate CycloneDX SBOMs for your application or library
 * Compatible with Rollup and Vite.
 */
export default function rollupPluginSbom(userOptions?: RollupPluginSbomOptions): Plugin {
    const options = {
        ...DEFAULT_OPTIONS,
        ...userOptions,
    };

    let bom: CDX.Models.Bom;
    let dependencyInfoRegistry: ReturnType<typeof createDependencyInfoRegistry>;
    let registeredModules: Map<PackageId, CDX.Models.Component>;
    let rootComponent: CDX.Models.Component | undefined;
    let rootPackageJson: NormalizedPackageJson | undefined;

    const cdxExternalReferenceFactory = new CDX.Contrib.FromNodePackageJson.Factories.ExternalReferenceFactory();
    const cdxLicenseFactory = new CDX.Contrib.License.Factories.LicenseFactory(spdxExpressionParse);
    const cdxLicenseEvidenceGatherer = new CDX.Contrib.License.Utils.LicenseEvidenceGatherer();
    const cdxComponentBuilder = new CDX.Contrib.FromNodePackageJson.Builders.ComponentBuilder(
        cdxExternalReferenceFactory,
        cdxLicenseFactory,
    );

    const jsonSerializer = new CDX.Serialize.JsonSerializer(
        new CDX.Serialize.JSON.Normalize.Factory(CDX.Spec.SpecVersionDict[options.specVersion]!),
    );
    const xmlSerializer = new CDX.Serialize.XmlSerializer(
        new CDX.Serialize.XML.Normalize.Factory(CDX.Spec.SpecVersionDict[options.specVersion]!),
    );

    function processExternalModuleForBom(context: PluginContext, mod: ExternalModuleInfo) {
        const dependencyInfo = dependencyInfoRegistry.get(mod.modulePath);
        if (!dependencyInfo) {
            const logFn = mod.isTransitive ? context.debug : context.warn;
            logFn({
                message: `Missing dependency info for module ${mod.modulePath} in registry, this should not happen (ID: ${mod.moduleId})`,
                meta: mod,
            });
        }

        const { pkg, licenseEvidence } = dependencyInfo || {};
        if (!pkg || !pkg.name || !pkg.version) {
            const logFn = mod.isTransitive ? context.debug : context.warn;
            logFn({
                message: `Missing package data for module ${mod.modulePath} in registry, this should not happen (ID: ${mod.moduleId})`,
                meta: mod,
            });
            return;
        }

        const packageId = generatePackageId(pkg);
        const doesComponentExist = registeredModules.has(packageId);
        const component: CDX.Models.Component | undefined =
            registeredModules.get(packageId) ?? cdxComponentBuilder.makeComponent(pkg);

        if (!component) {
            context.warn(`Failed to create component for ${pkg.name}@${pkg.version}`);
            return;
        }

        if (!doesComponentExist) {
            context.debug({
                message: `Registering package ${pkg?.name}@${pkg?.version}`,
                meta: mod,
            });

            const componentPurl = composePackageUrlFromPackageJson(pkg);
            if (componentPurl) {
                component.purl = componentPurl.toString();
                component.bomRef.value = componentPurl.toString();
            } else {
                context.warn(`Failed to compose package URL for ${pkg.name}@${pkg.version}`);
            }

            component.licenses.forEach((l) => {
                l.acknowledgement = CDX.Enums.LicenseAcknowledgement.Declared;
            });

            if (options.collectLicenseEvidence && Array.isArray(licenseEvidence) && licenseEvidence.length > 0) {
                component.evidence = new CDX.Models.ComponentEvidence({
                    licenses: new CDX.Models.LicenseRepository(licenseEvidence),
                });

                context.debug({
                    message: `Attaching ${component.evidence.licenses.size} license evidence to ${pkg?.name}@${pkg?.version}`,
                    meta: component.evidence,
                });
            }

            registeredModules.set(packageId, component);
            bom.components.add(component);

            // register direct dependencies on the root component itself
            if (rootPackageJson?.dependencies && pkg.name in rootPackageJson.dependencies) {
                rootComponent?.dependencies.add(component.bomRef);
            }
        }

        // Always add dependencies even for already registered components
        mod.dependsOn.forEach((externalDependencyModuleInfo) => {
            const dependencyComponent = processExternalModuleForBom(context, externalDependencyModuleInfo);
            if (dependencyComponent) {
                component.dependencies.add(dependencyComponent.bomRef);
            } else {
                context.debug(
                    `Skipped adding dependency for ${externalDependencyModuleInfo.modulePath}: component unavailable`,
                );
            }
        });

        return component;
    }

    /**
     * Adds a vendored package as a nested component of the package that contains its code
     */
    function addVendoredComponent(context: PluginContext, parent: CDX.Models.Component, vendored: VendoredPackage) {
        const vendoredPkg = { ...vendored.pkg, version: vendored.version };
        const purl = composePackageUrlFromPackageJson(vendoredPkg)?.toString();
        // Two installed copies of the parent package can contain the same vendored package
        if ([...parent.components].some((sibling) => sibling.purl?.toString() === purl)) {
            return;
        }
        const component = cdxComponentBuilder.makeComponent(vendoredPkg);
        if (!component) {
            context.warn(`Failed to create component for ${vendoredPkg.name}@${vendoredPkg.version}`);
            return;
        }
        if (purl) {
            component.purl = purl;
            // The same package can also be a top-level component, and bom-refs must be unique
            component.bomRef.value = `${parent.bomRef.value}|vendored:${purl}`;
        }
        component.licenses.forEach((l) => {
            l.acknowledgement = CDX.Enums.LicenseAcknowledgement.Declared;
        });
        component.properties.add(new CDX.Models.Property(`${PLUGIN_ID}:vendored:detection`, "code-fingerprint"));
        component.properties.add(
            new CDX.Models.Property(
                `${PLUGIN_ID}:vendored:matched-fingerprints`,
                `${vendored.matchedFingerprints}/${vendored.totalFingerprints}`,
            ),
        );
        component.properties.add(
            new CDX.Models.Property(`${PLUGIN_ID}:vendored:declared-version`, vendored.declaredVersion),
        );
        component.properties.add(
            new CDX.Models.Property(`${PLUGIN_ID}:vendored:fingerprinted-version`, vendored.pkg.version),
        );
        parent.components.add(component);
        context.info(
            `Detected vendored ${vendoredPkg.name}@${vendoredPkg.version} in ${parent.name}@${parent.version} (${vendored.matchedFingerprints}/${vendored.totalFingerprints} fingerprints)`,
        );

        vendored.vendored.forEach((child) => addVendoredComponent(context, component, child));
    }

    /**
     * Adds the dependencies whose code bundled packages copied into their own files
     */
    async function addVendoredComponents(context: PluginContext, tree: Set<ExternalModuleInfo>) {
        const minMatchedFingerprints =
            (typeof options.detectVendoredPackages === "object" &&
                options.detectVendoredPackages.minMatchedFingerprints) ||
            DEFAULT_MIN_MATCHED_FINGERPRINTS;
        const detector = createVendoredPackageDetector(context, minMatchedFingerprints);

        const bundledModulesByPackageDir = new Map<
            string,
            { pkg: NormalizedPackageJson; moduleIds: ModuleIdString[]; importedPackageDirs: Set<string> }
        >();
        for (const mod of tree) {
            const info = dependencyInfoRegistry.get(mod.modulePath);
            if (!info) {
                continue;
            }
            const entry = bundledModulesByPackageDir.get(info.path) ?? {
                pkg: info.pkg,
                moduleIds: [],
                importedPackageDirs: new Set(),
            };
            entry.moduleIds.push(mod.moduleId);
            for (const imported of mod.dependsOn) {
                const importedInfo = dependencyInfoRegistry.get(imported.modulePath);
                if (importedInfo) {
                    entry.importedPackageDirs.add(importedInfo.path);
                }
            }
            bundledModulesByPackageDir.set(info.path, entry);
        }

        for (const [packageDir, { pkg, moduleIds, importedPackageDirs }] of bundledModulesByPackageDir) {
            const host = registeredModules.get(generatePackageId(pkg));
            if (!host) {
                continue;
            }
            for (const vendored of await detector.detect(pkg, packageDir, moduleIds, importedPackageDirs)) {
                addVendoredComponent(context, host, vendored);
            }
        }
    }

    return {
        name: PLUGIN_ID,
        async buildStart() {
            bom = new CDX.Models.Bom({
                metadata: new CDX.Models.Metadata({
                    supplier: options.supplier && convertOrganizationalEntityOptionToModel(options.supplier),
                    properties:
                        options.properties &&
                        new CDX.Models.PropertyRepository(
                            options.properties.map(({ name, value }) => new CDX.Models.Property(name, value)),
                        ),
                }),
            });
            dependencyInfoRegistry = createDependencyInfoRegistry();
            registeredModules = new Map();
            rootComponent = undefined;
            rootPackageJson = undefined;

            // autoregister root entry when starting the build
            if (options.autodetect) {
                try {
                    this.debug(`Autodetection enabled, trying to resolve root component`);
                    const rootPkg = await readPackage(process.cwd());
                    if (rootPkg) {
                        this.info(`Detected root ${rootPkg.name} v${rootPkg.version}`);
                        rootPackageJson = rootPkg;

                        rootComponent = cdxComponentBuilder.makeComponent(
                            rootPkg,
                            options.rootComponentType as ComponentType,
                        );
                        if (!rootComponent) {
                            this.error({
                                message: `could not construct root component`,
                            });
                        }

                        rootComponent.version = rootPkg.version;
                        const rootComponentPurl = composePackageUrlFromPackageJson(rootPkg);
                        if (rootComponentPurl) {
                            rootComponent.purl = rootComponentPurl.toString();
                            rootComponent.bomRef.value = rootComponentPurl.toString();
                        } else {
                            this.warn(`Failed to compose package URL for ${rootPkg.name}@${rootPkg.version}`);
                        }

                        bom.metadata.component = rootComponent;
                    }
                } catch (err) {
                    this.error({
                        message: `autodetection failed: ${err instanceof Error ? err.message : err}`,
                        meta: {
                            error: err,
                        },
                    });
                }
            }

            // add lifecycle on build start
            bom.metadata.lifecycles.add(CDX.Enums.LifecyclePhase.Build);

            if (options.saveTimestamp) {
                this.info(`Saving timestamp to SBOM`);
                bom.metadata.timestamp = new Date();
            }

            if (options.generateSerial) {
                this.info(`Generating random serial number for SBOM`);
                bom.serialNumber = CDX.Contrib.Bom.Utils.randomSerialNumber();
            }

            // register known tools in the chain
            await autoRegisterTools(
                this,
                bom,
                cdxComponentBuilder,
                options.collectLicenseEvidence ? cdxLicenseEvidenceGatherer : undefined,
            );

            // apply custom information if configured
            if (options.beforeCollect) {
                this.debug('Applying custom transform "beforeCollect"');
                options.beforeCollect(bom);
            }
        },
        /**
         * We use this hook to load normalized package.json data and module specific info for each imported module.
         * As this hook runs in parallel before finishing the bundle, we can ensure that
         * all required package.json files are loaded before we start the BOM generation.
         */
        async moduleParsed(moduleInfo) {
            await aggregateDependencyInfoByModuleId(
                this,
                dependencyInfoRegistry,
                moduleInfo.id,
                options.collectLicenseEvidence ? cdxLicenseEvidenceGatherer : undefined,
            );
        },
        /**
         * Build the SBOM and emit files
         */
        async generateBundle(_outputOptions, bundle) {
            const tree = await getAllExternalModules(this, bundle);
            // ensure all dependency info is available before processing
            for (const mod of tree) {
                if (!dependencyInfoRegistry.has(mod.modulePath)) {
                    await aggregateDependencyInfoByModulePath(
                        this,
                        dependencyInfoRegistry,
                        mod.modulePath,
                        options.collectLicenseEvidence ? cdxLicenseEvidenceGatherer : undefined,
                    );
                }
            }
            // process each module and register it in the BOM
            for (const mod of tree) {
                processExternalModuleForBom(this, mod);
            }

            const serializeOptions: CDX.Serialize.Types.SerializerOptions & CDX.Serialize.Types.NormalizerOptions = {
                sortLists: options.sortLists,
                space: "\t",
            };

            const formatMap: Record<string, CDX.Serialize.BaseSerializer<unknown>> = {
                json: jsonSerializer,
                xml: xmlSerializer,
            };

            if (options.detectVendoredPackages) {
                await addVendoredComponents(this, tree);
            }

            if (options.afterCollect) {
                this.debug('Applying custom transform "afterCollect"');
                options.afterCollect(bom);
            }

            options.outFormats.forEach((format) => {
                if (!formatMap[format]) {
                    throw new Error(`Unsupported format: ${format}`);
                }

                // serialize the BOM and emit the file
                const sbomFilePath = join(options.outDir, `${options.outFilename}.${format}`);
                this.debug(`Emitting SBOM asset to ${sbomFilePath}`);
                this.emitFile({
                    type: "asset",
                    fileName: sbomFilePath,
                    needsCodeReference: false,
                    source: formatMap[format].serialize(bom, serializeOptions),
                });
            });

            // emit the .well-known/sbom file
            if (options.includeWellKnown) {
                this.debug(`Emitting well-known file to .well-known/sbom`);
                this.emitFile({
                    type: "asset",
                    fileName: ".well-known/sbom",
                    needsCodeReference: false,
                    source: jsonSerializer.serialize(bom, serializeOptions),
                });
            }
        },
    } satisfies Plugin;
}
